-- ----------------------------
-- Table structure for yzn_tradelist
-- ----------------------------
DROP TABLE IF EXISTS `yzn_tradelist`;
CREATE TABLE `yzn_tradelist` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '栏目ID',
  `leibie` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '类别',
  `pinlei` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '品类',
  `operation_time` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '操作日期',
  `kehu` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '客户',
  `trade` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '贸易链',
  `trade_id` int(11) DEFAULT NULL,
  `pinming` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '品名',
  `cangku` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '仓库',
  `hetongshuliang` decimal(11,2) DEFAULT NULL COMMENT '合同数量',
  `shitishuliang` decimal(15,5) DEFAULT NULL COMMENT '实提数量',
  `jinhuohetongbianhao` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '进货合同编号',
  `jinhuodanwei` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '进货单位',
  `jinhuodanjia` decimal(11,2) DEFAULT '0.00' COMMENT '进货单价',
  `shifuhuokuan` decimal(11,2) DEFAULT '0.00' COMMENT '实付货款',
  `yingfuhuokuan` decimal(11,2) DEFAULT '0.00' COMMENT '应付货款',
  `weikuan` decimal(11,2) DEFAULT '0.00' COMMENT '尾款',
  `xiaoshouhetongbianhao` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '销售合同编号',
  `xiaohuodanwei` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '销售单位',
  `xiaoshoudanjia` decimal(11,2) DEFAULT '0.00' COMMENT '销售单价',
  `shishouhuokuan` decimal(11,2) DEFAULT '0.00' COMMENT '实收货款',
  `yingshouhuokuan` decimal(11,2) DEFAULT '0.00' COMMENT '应收货款',
  `weikuan2` decimal(11,2) DEFAULT '0.00' COMMENT '尾款2',
  `danjiacha` decimal(11,2) DEFAULT '0.00' COMMENT '单价差',
  `jinecha2` decimal(11,2) DEFAULT '0.00' COMMENT '金额差2',
  `yingfu` decimal(11,2) DEFAULT '0.00' COMMENT '应付',
  `remark` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '括号',
  `yingshou` decimal(11,2) DEFAULT '0.00' COMMENT '应收',
  `trade_str` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jinxiangfapiao` tinyint(3) DEFAULT NULL COMMENT '进项发票',
  `xiaoshoufapiao` tinyint(3) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=497 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='栏目表';

